def calculate_final_amount(order_sum, requested_codes, available_discounts):
    current_sum = order_sum
    rejected = []
    for item in requested_codes:
        if item in available_discounts:
            val = available_discounts[item]
            try:
                current_sum -= val
            except TypeError:
                pass
        else:
            rejected.append(item)
    return {'total': current_sum, 'rejected': rejected}
